/**
 * Generates docs/reference/cli.md from the real CLI (help text + rule list).
 *
 * The reference is a build artifact committed to the repo: CI regenerates it
 * and fails on any diff, so docs can never describe flags that do not exist.
 * Never hand-edit the generated file — change the CLI, regenerate, commit.
 *
 * Usage:
 *   node scripts/gen-cli-docs.mjs          # regenerate docs/reference/cli.md
 *   node scripts/gen-cli-docs.mjs --check  # exit 1 if the committed file is stale
 * Requires `dist/` (run `npm run build` first).
 */
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const OUT = path.join(ROOT, 'docs/reference/cli.md');

function run(args) {
  try {
    return execFileSync('node', ['dist/cli.js', ...args], { encoding: 'utf8', cwd: ROOT });
  } catch {
    console.error('gen-cli-docs: dist/cli.js failed — run `npm run build` first.');
    process.exit(2);
  }
}

// NOTE: the blank line after the HTML comment is load-bearing — prettier
// inserts it, and the --check gate compares bytes, so the generator must
// emit prettier-stable output or the two CI jobs fight each other forever.
const doc =
  '<!-- GENERATED by scripts/gen-cli-docs.mjs — do not hand-edit. -->\n' +
  '\n' +
  '# CLI reference (generated)\n' +
  '\n' +
  'Regenerated from the built CLI. If this file disagrees with `--help`, ' +
  'the file is stale — run `node scripts/gen-cli-docs.mjs` and commit.\n' +
  '\n' +
  '## `usat --help`\n' +
  '\n' +
  '```\n' +
  run(['--help']).trimEnd() +
  '\n```\n' +
  '\n' +
  '## `usat rules`\n' +
  '\n' +
  '```\n' +
  run(['rules']).trimEnd() +
  '\n```\n';

if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : null;
  if (current !== doc) {
    console.error(
      'docs/reference/cli.md is stale — run `node scripts/gen-cli-docs.mjs` and commit the result.',
    );
    process.exit(1);
  }
  console.log('CLI reference: OK (in sync)');
} else {
  fs.writeFileSync(OUT, doc);
  console.log(`wrote ${path.relative(ROOT, OUT)}`);
}
